ValidationRule.errorConditionFormula:
AND(
  ISPICKVAL( SOL_Tipo_Tarefa__c , "Fechamento" ),
  OR( ISNEW(), ISCHANGED( Status ) ),
  OR(
    AND(
      ISPICKVAL( Status , "Completed" ),
      NOT( SOL_Encerrado_Pela_Oportunidade__c )
    ),
    AND(
      ISPICKVAL( Status , "Cancelada" ),
      NOT(
        AND(
          SOL_Cancelada_Por_Perda__c,
          ISPICKVAL( SOL_Motivo_Cancelamento__c , "Negócio perdido" )
        )
      )
    )
  )
)
